#!/usr/bin/env bash
# Some portions generated by Codex. Candidate family only over immutable actual-HTTP runtimes.
set -euo pipefail
cd "$(dirname "$0")/../../.."
D=experiments/threadlocal-audit/compact-json
exec 9>experiments/overlay/native-benchmark.lock
flock 9
for arm in base depth; do
 cp="$PWD/$D/candidate-layer:$PWD/tools/workbench/target/test-classes:$(cat experiments/threadlocal-audit/read-resource-workbench/cp-$arm.txt):$(cat experiments/threadlocal-audit/read-depth/cp_a.txt)"
