 ../toolchain/jdk-25.0.5+8/bin/java -javaagent:$PWD/.m2_repo/org/mockito/mockito-core/5.24.0/mockito-core-5.24.0.jar --source 25 -cp "$cp" "$D/FocusedLauncher.java" org.eclipse.rdf4j.workbench.util.WorkbenchCompactTokenWriterTest org.eclipse.rdf4j.workbench.util.WorkbenchPageResultWriterTest > "$D/isolated-$arm.log" 2>&1
 echo "isolated_arm=$arm exit=0"
done
